import clsx from 'clsx';
import React from 'react';
import type {
  OptionProps as ReactSelectOptionProps,
  GroupBase,
} from 'react-select';

import { CheckmarkSmallIcon } from '@dynatrace/strato-icons';

import { _useFocusContext } from '../../../core/hooks/useFocusContext.js';
import { _isStringChildren } from '../../../core/utils/is-string-children.js';
import { Flex } from '../../../layouts-core/flex/Flex.js';
import { TextEllipsis } from '../../../typography/TextEllipsis.js';
import { useSelectMenuContext } from '../hooks/use-select-menu-context.js';
import { SelectActions } from '../state/select-menu-state-reducer.js';
import {
  selectOptionMultiCSS,
  selectOptionMultiIndicatorCSS,
  selectOptionMultiIndicatorIconCSS,
  selectOptionPrefixCSS,
  selectOptionSingleCSS,
  selectOptionSuffixCSS,
} from '../styles/Select.sty.js';
import type { _BaseOption, _BaseGroup } from '../types.js';

export type OptionProps<
  OptionValue,
  isMulti extends boolean,
  Group extends GroupBase<OptionValue>,
> = ReactSelectOptionProps<OptionValue, isMulti, Group>;

export function Option<
  OptionValue,
  isMulti extends boolean,
  Group extends _BaseGroup<OptionValue>,
>(props: OptionProps<_BaseOption<OptionValue>, isMulti, Group>) {
  const {
    children,
    isSelected,
    innerProps,
    isFocused,
    isDisabled,
    isMulti,
    selectProps,
  } = props;
  const {
    className: consumerClassName,
    style: consumerStyle,
    'data-testid': dataTestId,
    prefix,
    suffix,
  } = props.data;

  const { dispatch } = useSelectMenuContext();

  const focusContext = _useFocusContext();

  const childIsText = _isStringChildren(children);

  return (
    <Flex
      data-testid={dataTestId}
      role="option"
      {...innerProps}
      className={clsx(
        'strato-selectV2-option',
        isMulti === true ? selectOptionMultiCSS : selectOptionSingleCSS,
        {
          'strato-selectV2-option--selected': isSelected,
          'strato-selectV2-option--focus':
            selectProps.focusOnOption && focusContext.modality === 'keyboard'
              ? isFocused
              : false,
          'strato-selectV2-option--disabled': isDisabled,
        },
        consumerClassName,
      )}
      style={consumerStyle}
      onClick={(evt) => {
        if (!isDisabled) {
          // Only if the option is in single select mode and the clicked
          // option is not yet selected, we can close the menu.
          if (isMulti === false && isSelected === false) {
            dispatch({
              type: SelectActions.CLOSE,
            });
          }
          innerProps.onClick?.(evt);
        }
      }}
      aria-selected={isSelected}
    >
      {isMulti === true ? (
        <div
          className={clsx(
            selectOptionMultiIndicatorCSS({
              selected: isSelected,
            }),
          )}
        >
          {isSelected === true ? (
            <CheckmarkSmallIcon className={selectOptionMultiIndicatorIconCSS} />
          ) : null}
        </div>
      ) : null}
      {/* Check if any of the options have a prefix defined. If they do, all other items will need to respect the space */}
      {props.selectProps.optionsHavePrefix ? (
        <span
          className={clsx(
            selectOptionPrefixCSS,
            prefix.componentProps?.className,
          )}
          style={prefix.componentProps?.style}
          data-testid={prefix.componentProps?.['data-testid']}
        >
          {prefix.component}
        </span>
      ) : null}
      {childIsText ? (
        <TextEllipsis>{children as string}</TextEllipsis>
      ) : (
        children
      )}
      {/* For the Suffix icon, we will not need to deal with the other options. Overlaps are fine here. */}
      {suffix.component ? (
        <span
          className={clsx(
            selectOptionSuffixCSS,
            suffix.componentProps?.className,
          )}
          style={suffix.componentProps?.style}
          data-testid={suffix.componentProps?.['data-testid']}
        >
          {suffix.component}
        </span>
      ) : null}
    </Flex>
  );
}
